import{_ as t,c as a,o as s,a2 as n}from"./chunks/framework.PGES7OoM.js";const d=JSON.parse(`{"title":"Swap assets privately","description":"","frontmatter":{"rawMarkdown":"# Swap assets privately\\n\\nCurvy's built-in swap exchanges assets inside your private balance. Open **Swap** from the app's main navigation.\\n\\nThe swap UI is made to feel familiar to users of the popular DEXs:\\n\\n1. Under **You pay**, choose the asset and enter the amount. You can also enter the amount in dollars.\\n2. Choose the asset you want to receive. The reverse button flips the two sides.\\n3. An indicative rate is shown while you type; the exact amounts are calculated in the review.\\n4. Choose **Review swap**.\\n\\nThe review shows a detailed breakdown of the swap, including the rate and the associated fees.\\nRates can move while you are reviewing, so if the quote expires, check the updated amount before confirming.\\n\\nAfter confirming, the swap opens its execution page. Keep it open until the swap finishes; you can follow the\\nexecution of the swap, as well as the shielding of the resulting swapped assets. The new assets appear in your Curvy balance after settlement,\\nand the swap is listed under **Activity**, including recovery options if it was interrupted.\\n","rawMarkdownPath":"/_raw/for-users/swap-assets-privately.md","rawMarkdownTitle":"Swap assets privately","rawMarkdownUrl":"https://docs.curvy.box/_raw/for-users/swap-assets-privately.md"},"headers":[],"relativePath":"for-users/swap-assets-privately.md","filePath":"for-users/swap-assets-privately.md","lastUpdated":1791449043000}`),i={name:"for-users/swap-assets-privately.md"};function o(r,e,p,l,h,w){return s(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="swap-assets-privately" tabindex="-1">Swap assets privately <a class="header-anchor" href="#swap-assets-privately" aria-label="Permalink to &quot;Swap assets privately&quot;">​</a></h1><p>Curvy&#39;s built-in swap exchanges assets inside your private balance. Open <strong>Swap</strong> from the app&#39;s main navigation.</p><p>The swap UI is made to feel familiar to users of the popular DEXs:</p><ol><li>Under <strong>You pay</strong>, choose the asset and enter the amount. You can also enter the amount in dollars.</li><li>Choose the asset you want to receive. The reverse button flips the two sides.</li><li>An indicative rate is shown while you type; the exact amounts are calculated in the review.</li><li>Choose <strong>Review swap</strong>.</li></ol><p>The review shows a detailed breakdown of the swap, including the rate and the associated fees. Rates can move while you are reviewing, so if the quote expires, check the updated amount before confirming.</p><p>After confirming, the swap opens its execution page. Keep it open until the swap finishes; you can follow the execution of the swap, as well as the shielding of the resulting swapped assets. The new assets appear in your Curvy balance after settlement, and the swap is listed under <strong>Activity</strong>, including recovery options if it was interrupted.</p>',6)])])}const c=t(i,[["render",o]]);export{d as __pageData,c as default};
